// Normalize the OpenAI extraction into a clean, predictable slot object.
const called = $('When Called').first().json || {};

const tj = $('Whisper_Transcribe').isExecuted ? ($('Whisper_Transcribe').first().json || {}) : {};
const transcript = (tj.text || tj.transcript || tj.output || '').toString().trim();

const ej = $('Extract_Slots').isExecuted ? ($('Extract_Slots').first().json || {}) : {};

function findPayload(o) {
  if (o == null) return null;
  if (typeof o === 'string') return o;
  if (typeof o === 'object') {
    if (Array.isArray(o.output)) {
      for (const msg of o.output) {
        const content = msg && msg.content;
        if (Array.isArray(content)) {
          for (const c of content) {
            if (c && c.text != null) return c.text;
            if (c && typeof c === 'string') return c;
          }
        }
      }
    }
    if (o.text != null)    return o.text;
    if (o.content != null) return o.content;
    if (o.message != null) return o.message;
    if (o.response != null) return o.response;
    if (o.intent != null)  return o;
  }
  return o;
}

function parseJson(s) {
  if (!s) return {};
  if (typeof s === 'object') return s;
  try { return JSON.parse(s); } catch (e) {}
  const m = String(s).match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return {};
}

const slots = parseJson(findPayload(ej));

const clean = (v) => (v === undefined || v === null) ? '' : String(v).trim();
function detectLang(s) {
  const t = (s || '').toString();
  if (/[؀-ۿ]/.test(t)) return 'ar';   // Arabic
  if (/[Ѐ-ӿ]/.test(t)) return 'ru';   // Cyrillic
  if (/[一-鿿]/.test(t)) return 'zh';   // CJK
  if (/[ऀ-ॿ]/.test(t)) return 'hi';   // Devanagari
  return 'en';
}
const VEHICLES = ['saloon','estate','mpv','8seater','wheelchair'];
let vehicle = clean(slots.vehicle).toLowerCase().replace(/[^a-z0-9]/g, '');
if (vehicle === '6seater' || vehicle === 'sixseater' || vehicle === 'peoplecarrier' || vehicle === 'minivan') vehicle = 'mpv';
if (vehicle === 'eightseater' || vehicle === 'minibus') vehicle = '8seater';
if (vehicle === 'sedan' || vehicle === 'standard' || vehicle === 'car') vehicle = 'saloon';
if (!VEHICLES.includes(vehicle)) vehicle = '';

const VALID_INTENTS = ['book','airport','quote','manage','modify','cancel','change','answer','unknown'];
let intent = clean(slots.intent).toLowerCase();
if (!VALID_INTENTS.includes(intent)) intent = 'unknown';

const passengersNum = parseInt(slots.passengers, 10);

const lugRaw = (slots.luggage === undefined || slots.luggage === null) ? '' : slots.luggage;
const luggage = lugRaw === true || ['true','yes','y','1','some','lots','heavy','large','extra'].includes(String(lugRaw).trim().toLowerCase());

return [{ json: {
  ok: transcript.length > 0,
  transcript,
  language:         detectLang(transcript),
  intent,
  pickup:           clean(slots.pickup),
  destination:      clean(slots.destination),
  whenText:         clean(slots.whenText || slots.when || slots.time || slots.datetime),
  vehicle,
  passengers:       Number.isFinite(passengersNum) ? passengersNum : null,
  luggage,
  passengerName:    clean(slots.passengerName || slots.name),
  note:             clean(slots.note || slots.driverNote),
  airport:          clean(slots.airport || slots.airportName),
  terminal:         clean(slots.terminal),
  flightNumber:     clean(slots.flightNumber || slots.flight).toUpperCase().replace(/\s+/g, ''),
  bookingReference: clean(slots.bookingReference || slots.bookingId || slots.reference).replace(/[^0-9]/g, ''),
  phone:            clean(called.phone),
  fromStep:         clean(called.step)
}}];
